// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type PremiumListGraphicProps = Record<string, any>;

const PremiumListGraphic: React.FC<PremiumListGraphicProps> = ({
  backgroundColor = "#09090b", // Minimalist dark neutral
  transparentBackground = false,
  durationInSeconds = 7,
  items = ["Basic Search", "Color Search", "Theme Search"],
  textColor = "#f8fafc",
  ambientLightColor = "#3b0764", // Subtle premium AI aura (dark purple)
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;
  
  // Responsive sizing baseline
  const minDimension = Math.min(width, height);

  // Ambient Light Logic (Soft drifting background)
  const ambientX = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [width * 0.4, width * 0.6]
  );
  const ambientY = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [height * 0.6, height * 0.4]
  );
  const ambientScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.4]
  );
  const ambientOpacity = interpolate(
    frame,
    [0, fps * 2],
    [0, 0.5],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Continuous subtle upward drift of the entire container
  const groupDrift = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0, -height * 0.05]
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
      }}
    >
      {/* Ambient Gradient Background */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: minDimension * 1.5,
            height: minDimension * 1.5,
            left: ambientX - (minDimension * 1.5) / 2,
            top: ambientY - (minDimension * 1.5) / 2,
            background: `radial-gradient(circle, ${ambientLightColor} 0%, transparent 60%)`,
            transform: `scale(${ambientScale})`,
            opacity: ambientOpacity,
            filter: "blur(80px)",
            transition: "none",
          }}
        />
      )}

      {/* Inline SVG Grain Overlay for Subtle Depth */}
      {!transparentBackground && (
        <svg
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            opacity: 0.04,
            mixBlendMode: "overlay",
            pointerEvents: "none",
            transition: "none",
          }}
        >
          <filter id="premiumNoise">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.8"
              numOctaves="3"
              stitchTiles="stitch"
            />
          </filter>
          <rect width="100%" height="100%" filter="url(#premiumNoise)" />
        </svg>
      )}

      {/* Main List Container */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          justifyContent: "center",
          paddingLeft: width * 0.15,
          paddingRight: width * 0.1,
          gap: minDimension * 0.1, // Increased gap
          transform: `translateY(${groupDrift}px)`,
          transition: "none",
        }}
      >
        {items.map((item, index) => {
          // Staggered timing with longer pauses
          const startDelay = fps * 1.2; // 1.2s pause on empty frame before start
          const stagger = fps * 1.8; // 1.8s between each line (longer pause)
          const itemStartFrame = startDelay + index * stagger;

          // Smooth Spring for the slide reveal
          const revealProgress = spring({
            fps,
            frame: frame - itemStartFrame,
            config: {
              damping: 18,
              stiffness: 55,
              mass: 1.2,
            },
          });

          // Soft drift instead of full wipe since we are using a blur reveal
          const translateY = interpolate(revealProgress, [0, 1], [40, 0]);

          // Soft Fade-in
          const opacity = interpolate(
            frame - itemStartFrame,
            [0, fps * 1], // Fades in over 1 second
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Blur-in effect
          const blurAmount = interpolate(
            frame - itemStartFrame,
            [0, fps * 1.2], // Blurs out over 1.2 seconds
            [24, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={index}
              style={{
                position: "relative",
                padding: "8px 0",
                display: "flex",
                justifyContent: "flex-start",
                alignItems: "center",
                transition: "none",
                width: "100%",
              }}
            >
              <h2
                style={{
                  margin: 0,
                  fontSize: minDimension * 0.085, // Scale cleanly vertically or horizontally
                  fontWeight: 600,
                  color: textColor,
                  letterSpacing: "-0.015em",
                  transform: `translateY(${translateY}%)`,
                  opacity: opacity,
                  filter: `blur(${blurAmount}px)`,
                  transition: "none",
                  textAlign: "left",
                  lineHeight: 1.1,
                }}
              >
                {item}
              </h2>
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PremiumListGraphic;